wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(39586768606298361)
,p_process_sequence=>110
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cargar estructura'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'begin',
'  select count(*) into :P10_TOTAL from SPD_GOAL where NIT_COMPANIA = :G_NIT_COMPANIA;',
unistr('  -- plan por defecto: el activo de la compa\00F1\00EDa (o el m\00E1s reciente)'),
'  if :P10_PLAN is null then',
'    select max(PLAN) keep (dense_rank first order by case when SPD_ACTIVO = ''S'' then 0 else 1 end, PLAN desc)',
'      into :P10_PLAN from PLAN_DESARROLLO where NIT_COMPANIA = :G_NIT_COMPANIA;',
'  end if;',
'  :P10_NODE := nvl(:P10_NODE, ''0'');',
'  if :P10_NODE <> ''0'' then',
'    begin',
'      select CODE || '' '' || NAME into :P10_NODE_NAME from SPD_DEV_PLAN_LEVEL',
'       where ID = :P10_NODE and NIT_COMPANIA = :G_NIT_COMPANIA and PLAN = :P10_PLAN;',
'    exception when no_data_found then :P10_NODE := ''0'';',
'    end;',
'  end if;',
'  if :P10_NODE = ''0'' then',
'    select max(NOMBRE) into :P10_NODE_NAME from PLAN_DESARROLLO where NIT_COMPANIA = :G_NIT_COMPANIA and PLAN = :P10_PLAN;',
'  end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>39586768606298361
);
end;
