 p_id=>wwv_flow_imp.id(39138902949550225)
,p_process_sequence=>5
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Par\00E1metros: campos a JSON')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  function d(v varchar2) return varchar2 is',
'  begin',
'    return case when v is null then ''null'' else ''"'' || to_char(to_date(v, ''DD/MM/YYYY''), ''YYYY-MM-DD'') || ''T05:00:00.000Z"'' end;',
'  end;',
'begin',
'  :P46_DATES_CONFIG := ''{"scheduling": ['' || d(:P46_SCHED_FROM) || '', '' || d(:P46_SCHED_TO) || ''], ''',
'    || ''"reporting": [''  || d(:P46_REPORT_FROM) || '', '' || d(:P46_REPORT_TO) || ''], ''',
'    || ''"validating": ['' || d(:P46_VALID_FROM) || '', '' || d(:P46_VALID_TO) || ''], ''',
'    || ''"reviewing": [''  || d(:P46_REVIEW_FROM) || '', '' || d(:P46_REVIEW_TO) || '']}'';',
'  :P46_GOAL_TYPES := case when :P46_GOAL_TYPES_SEL is null then null else ''["'' || replace(:P46_GOAL_TYPES_SEL, '':'', ''","'') || ''"]'' end;',
'  :P46_SPENT_DOCS := case when :P46_SPENT_DOCS_SEL is null then null else ''["'' || replace(:P46_SPENT_DOCS_SEL, '':'', ''","'') || ''"]'' end;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>39138902949550225
);
